function ShowWiringTwoButton(opts)
    arguments
        opts.Enable (1,1) logical = false;
        opts.HighlightWiring (1,1) logical = false;
        opts.ExternalFigure (1,1) logical = false;
    end

    % Load image:
    if opts.HighlightWiring 
